<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';if($_SERVER['REQUEST_METHOD']!=='POST')exit('Invalid request.');$data=[trim($_POST['patient_code']??''),trim($_POST['philhealth_id']??''),trim($_POST['first_name']??''),trim($_POST['middle_name']??''),trim($_POST['last_name']??''),$_POST['birthdate']??'',$_POST['sex']??'',trim($_POST['address']??''),trim($_POST['contact_number']??'')];if($data[0]===''||$data[1]===''||$data[2]===''||$data[4]===''||$data[5]===''||$data[6]==='')exit('Required patient information is missing.');try{$s=$pdo->prepare('INSERT INTO patients(patient_code,philhealth_id,first_name,middle_name,last_name,birthdate,sex,address,contact_number) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute($data);$id=(int)$pdo->lastInsertId();header('Location:view.php?id='.$id);exit;}catch(PDOException $e){exit(str_contains($e->getMessage(),'Duplicate')?'Patient ID already exists.':$e->getMessage());}
